import { createWorkspace } from "@tigrisdata/agent-kit";
import { writeFileSync } from "fs";
import { join } from "path";

async function main() {
  const now = new Date();
  const workspaceName = "long-running-eval-ws";

  const { workspace, error } = await createWorkspace(workspaceName, {
    ttl: { days: 7 },
    credentials: { role: "ReadOnly" },
  });

  if (error) {
    console.error("Error creating workspace:", error);
    process.exit(1);
  }

  if (!workspace) {
    console.error("No workspace returned");
    process.exit(1);
  }

  // Calculate expiry: now + 7 days
  const expiresAt = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);

  const result = {
    bucket: workspace.bucket,
    expires_at: expiresAt.toISOString(),
  };

  writeFileSync(
    join("/home/user/ttl-workspace", "workspace.json"),
    JSON.stringify(result, null, 2)
  );

  console.log("Workspace provisioned successfully.");
}

main().catch((err) => {
  console.error("Fatal error:", err);
  process.exit(1);
});

